import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.D9E58p8B.js";const m=JSON.parse('{"title":"Looking at the screen","description":"","frontmatter":{"title":"Looking at the screen"},"headers":[],"relativePath":"en/agent/regarder.md","filePath":"en/agent/regarder.md"}'),r={name:"en/agent/regarder.md"};function i(s,e,d,h,c,l){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="looking-at-the-screen" tabindex="-1">Looking at the screen <a class="header-anchor" href="#looking-at-the-screen" aria-label="Permalink to &quot;Looking at the screen&quot;">​</a></h1><p>This is the starting point of almost every task: the agent sees what you see.</p><h2 id="what-you-ask" tabindex="-1">What you ask <a class="header-anchor" href="#what-you-ask" aria-label="Permalink to &quot;What you ask&quot;">​</a></h2><blockquote><p>&quot;Look at my screen and tell me which window is in the foreground.&quot;</p><p>&quot;Find the Save button on screen.&quot;</p></blockquote><h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><ol><li><a href="/Daimon/en/reference/vue.html#vue-displays"><code>vue_displays</code></a> lists the screens, with their index. With two screens, the agent knows which one to look at.</li><li><a href="/Daimon/en/reference/vue.html#vue-snapshot"><code>vue_snapshot</code></a> captures a screen. It returns a coordinate contract (<code>coord_space</code>) and then the image. By default the image is downscaled to 720 pixels wide: the agent asks for more for fine detail, or limits the capture to a <code>region</code>.</li><li><a href="/Daimon/en/reference/vue.html#vue-find"><code>vue_find</code></a> locates a <strong>visible</strong> label by on-device OCR and returns clickable coordinates. It is mostly used when <a href="/Daimon/en/agent/lire-interface.html">Touché</a> sees nothing.</li><li><a href="/Daimon/en/reference/vue.html#vue-resolve"><code>vue_resolve</code></a> converts a pixel of the image into a global point, and the reverse, without capturing: the agent does not have to compute offset and scale.</li></ol><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>A description, a position, or a clickable point. <strong>Daimon does not interpret the image</strong>: your agent looks at it and decides.</p><h2 id="what-daimon-masks" tabindex="-1">What Daimon masks <a class="header-anchor" href="#what-daimon-masks" aria-label="Permalink to &quot;What Daimon masks&quot;">​</a></h2><p>The windows of the applications you protect, the declared areas and the secret fields are never refused: they are <strong>censored</strong>, replaced by an opaque purple flat tint <code>#3A2A5C</code>. Your agent knows that an area of this color is masked content, not an empty screen. OCR reads the censored image: it returns no word that touches a censored area. See <a href="/Daimon/en/guide/confidentialite.html">Privacy</a>.</p><h2 id="if-the-call-is-refused" tabindex="-1">If the call is refused <a class="header-anchor" href="#if-the-call-is-refused" aria-label="Permalink to &quot;If the call is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Code</th><th>What the agent should do</th></tr></thead><tbody><tr><td><code>permission_denied</code></td><td>The <strong>Enregistrement de l&#39;écran</strong> (Screen Recording) permission is missing: <a href="/Daimon/en/guide/autorisations.html">Permissions</a></td></tr><tr><td><code>invalid_arguments</code></td><td>Fix the argument</td></tr><tr><td><code>index_out_of_range</code></td><td>The requested screen does not exist: re-read <code>vue_displays</code></td></tr><tr><td><code>capture_failed</code></td><td>Retry, then call <code>daimon_doctor</code></td></tr><tr><td><code>exclusions_unreadable</code></td><td>Your exclusions file is broken: the message names the file and the line</td></tr></tbody></table><p>Full detail: <a href="/Daimon/en/reference/vue.html">Vue</a>.</p><p>Next: <a href="/Daimon/en/agent/lire-interface.html">Reading an interface</a>, or <a href="/Daimon/en/agent/agir.html">Acting</a>.</p>',14)])])}const g=t(r,[["render",i]]);export{m as __pageData,g as default};
